<?php
require 'db.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['username']??'');$pw=$_POST['password']??'';$s=$conn->prepare('SELECT u.UserID,u.UserName,u.FullName,u.Password,r.RoleName FROM users u JOIN roles r ON r.RoleID=u.RoleID WHERE u.UserName=? OR u.Email=? LIMIT 1');$s->bind_param('ss',$name,$name);$s->execute();$u=$s->get_result()->fetch_assoc();if($u&&(password_verify($pw,$u['Password'])||hash_equals($u['Password'],md5($pw)))){if(hash_equals($u['Password'],md5($pw))){$hash=password_hash($pw,PASSWORD_DEFAULT);$up=$conn->prepare('UPDATE users SET Password=? WHERE UserID=?');$up->bind_param('si',$hash,$u['UserID']);$up->execute();}session_regenerate_id(true);$_SESSION['user_id']=(int)$u['UserID'];$_SESSION['username']=$u['UserName'];$_SESSION['full_name']=$u['FullName']?:$u['UserName'];$_SESSION['role']=$u['RoleName'];header('Location: index.php');exit;}else $error='Incorrect username/email or password.';}
page_start('Sign in');?><div class="form-container" style="margin:40px auto"><h2>Welcome back</h2><?php if($error):?><p class="pill"><?=h($error)?></p><?php endif;?><form method="post"><?php csrf_field();?><label>Username or email</label><input class="field" name="username" required autocomplete="username"><label>Password</label><input class="field" type="password" name="password" required autocomplete="current-password"><button>Sign in</button></form><p>New to MealDash? <a href="register.php">Create an account</a></p></div><?php page_end();
